fn first_even_odd_indices(lst: Vec<i32>) -> (usize, usize) {
    // Find the first index of an even element
    let first_even = lst
        .iter()
        .position(|&x| x % 2 == 0)
        .expect("At least one even element is guaranteed");

    // Find the first index of an odd element
    let first_odd = lst
        .iter()
        .position(|&x| x % 2 != 0)
        .expect("At least one odd element is guaranteed");

    (first_even, first_odd)
}

